sys_script_include.script:
var RewardUtils = Class.create();
RewardUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getDepartment: function(){
		var empId = this.getParameter('sysparm_empid');

		var userGr = new GlideRecordSecure('sys_user');
		if(userGr.get(empId)){
			return userGr.getValue('department');
		}
		return '';
	},

	getRemainingBudget: function(){
		var dept = this.getParameter('sysparm_dept');
		var quarter = this.getParameter('sysparm_quarter');
		var year = this.getParameter('sysparm_year');

		var deptRewardBudgetGr = new GlideRecordSecure('x_1921751_employ_0_department_reward_budget');
		deptRewardBudgetGr.addQuery('department', dept);
		deptRewardBudgetGr.addQuery('quarter', quarter);
		deptRewardBudgetGr.addQuery('year', year);
		deptRewardBudgetGr.setLimit(1);
		deptRewardBudgetGr.query();

		if(deptRewardBudgetGr.next()){
			return deptRewardBudgetGr.getValue('remaining_budget');
		}
		return '';
	},

	getRewardTypeDetails: function(){
		var rewardId = this.getParameter('sysparm_reward_id');

		var rewardCatalogGr = new GlideRecordSecure('x_1921751_employ_0_reward_catalog');
		if(rewardCatalogGr.get(rewardId)){
			return JSON.stringify({
				name: rewardCatalogGr.getValue('reward_type'),
				minValue: rewardCatalogGr.getValue('min_value'),
				maxValue: rewardCatalogGr.getValue('max_value'),
			});
		}
		return "Not Found";
	},

	fetchRewardType: function(){
		var rewardName = this.getParameter('sysparm_reward_name');
		var rewardType = '';

		switch(rewardName){
			case 'Spot Bonus - High Value':
				rewardType = gs.getProperty('x_1921751_employ_0.spot_bonus_reward_type');
				break;

			case 'Team Recognition Award':
				rewardType = gs.getProperty('x_1921751_employ_0.team_recognition_award_reward_type');
				break;

			case 'Extra Leave Credit':
				rewardType = gs.getProperty('x_1921751_employ_0.extra_leave_credit_reward_type');
				break;

			case 'Voucher Gift Card':
				rewardType = gs.getProperty('x_1921751_employ_0.voucher_gift_card_reward_type');
				break;

			default:
				rewardType = 'nil';
				break;
		}

		return rewardType;
	},

    type: 'RewardUtils'
});
